import { Component } from "@angular/core";
import * as Highcharts from "highcharts";

@Component({
    selector: "player-experience-analytics",
    templateUrl: "./player-experience-analytics.component.html",
    styleUrl: "./player-experience-analytics.component.css",
})
export class PlayerExperienceAnalyticsComponent {
    Highcharts: typeof Highcharts = Highcharts;
    chartOptions: Highcharts.Options = {
        chart: {
            type: "column",
        },
        title: {
            text: "Comparison of Self-Reported and Measured Player Experience in Collision Events",
        },
        subtitle: {
            text: "Emotion detection and player experience [219]",
        },
        xAxis: {
            categories: ["Anger", "Calm", "Happiness", "Sadness"],
            title: {
                text: "Emotion",
            },
        },
        yAxis: {
            min: 0,
            title: {
                text: "Percentage",
            },
        },
        tooltip: {
            shared: true,
            valueSuffix: "%",
        },
        plotOptions: {
            column: {
                grouping: true,
                shadow: false,
                borderWidth: 0,
            },
        },
        series: [
            {
                name: "Self-Reported",
                type: "column",
                data: [25, 35, 20, 20],
                color: "#7cb5ec",
            },
            {
                name: "Measured",
                type: "column",
                data: [30, 30, 25, 15],
                color: "#434348",
            },
        ],
        credits: {
            enabled: false,
        },
    };
}
