import { Component } from "@angular/core";
import * as Highcharts from "highcharts";

@Component({
    selector: "app-search-analytics",
    templateUrl: "./search-analytics.component.html",
    styleUrls: ["./search-analytics.component.css"],
})
export class SearchAnalyticsComponent {
    Highcharts: typeof Highcharts = Highcharts;

    chartOptions: Highcharts.Options = {
        chart: {
            type: "column",
        },
        title: {
            text: "Time spent with Web pages",
        },
        subtitle: {
            text:  "Web search strategies and performance [199]",
            //text: "(Web +/- refers to Web expertise, Econo +/- refers to domain knowledge)",
            style: {
                fontSize: "11px",
            },
        },
        xAxis: {
            categories: [
                "Page selected from search results",
                "Page accessed via browsing",
            ],
            title: {
                text: null,
            },
        },
        yAxis: {
            min: 0,
            max: 40,
            title: {
                text: "Seconds",
            },
        },
        tooltip: {
            shared: true,
            valueSuffix: " seconds",
        },
        plotOptions: {
            column: {
                grouping: true,
                shadow: false,
                borderWidth: 0,
            },
        },
        legend: {
            layout: "vertical",
            align: "right",
            verticalAlign: "middle",
        },
        series: [
            {
                name: "Web - Econo -",
                type: "column",
                data: [36, 22],
                color: "#c6d9f0",
            },
            {
                name: "Web - Econo +",
                type: "column",
                data: [29, 22],
                color: "#003399",
            },
            {
                name: "Web + Econo -",
                type: "column",
                data: [34, 19],
                color: "#fbd5b5",
            },
            {
                name: "Web + Econo +",
                type: "column",
                data: [23, 17],
                color: "#ff3300",
            },
        ],
        credits: {
            enabled: false,
        },
    };
}
